def _normalizar_telefono(raw, pk):
    digits = re.sub(r"\D", "", raw or "")
    if len(digits) == 12 and digits.startswith("57"):
        digits = digits[2:]
    if len(digits) > 10:
        digits = digits[:10] if digits.startswith("3") else digits[-10:]
    if not digits:
        digits = f"300{pk:07d}"[:10]
    elif len(digits) < 10:
        digits = digits.ljust(10, "0") if digits.startswith("3") else ("3" + digits).ljust(10, "0")[:10]
    return digits


def _normalizar_documento(raw, pk, tipo_doc, usados):
    digits = re.sub(r"\D", "", raw or "")
    if len(digits) > 10:
        digits = digits[:10]
    elif not digits:
        digits = f"100000{pk:04d}"[:10]
    elif len(digits) < 10:
        digits = f"1{digits.zfill(9)}"

    while (tipo_doc, digits) in usados:
        digits = f"{(int(digits) + 1) % 10**10:010d}"
    usados.add((tipo_doc, digits))
    return digits


